import{_ as a,o as t,c as i,a3 as s,j as e,a as r}from"./chunks/framework.z_KJ15Ep.js";const o="/bilder/vorbereitung/gruppenprozesse-epochal-faecher-2-gruppenprozess.png",h="/bilder/vorbereitung/gruppenprozesse-epochal-faecher-1-stundentafel.png",z=JSON.parse('{"title":"Epochalfächer und ihre Noten ergänzen","description":"","frontmatter":{"title":"Epochalfächer und ihre Noten ergänzen","source_pageid":823,"source_revision":5355},"headers":[],"relativePath":"zeugnisse/vorbereitung/noten-von-epochal-faechern-ergaenzen-gruppenprozesse-faecher.md","filePath":"zeugnisse/vorbereitung/noten-von-epochal-faechern-ergaenzen-gruppenprozesse-faecher.md"}'),p={name:"zeugnisse/vorbereitung/noten-von-epochal-faechern-ergaenzen-gruppenprozesse-faecher.md"};function c(l,n,u,d,g,m){return t(),i("div",null,[...n[0]||(n[0]=[s('<h1 id="epochalfacher-und-ihre-noten-erganzen" tabindex="-1">Epochalfächer und ihre Noten ergänzen <a class="header-anchor" href="#epochalfacher-und-ihre-noten-erganzen" aria-label="Permalink to &quot;Epochalfächer und ihre Noten ergänzen&quot;">​</a></h1><p>Übernehmen Sie im vorherigen Abschnitt abgeschlossenen Epochenunterricht mit seiner Note in den aktuellen Abschnitt. Die Fächer müssen zuvor entsprechend gekennzeichnet sein.</p><p>Der Gruppenprozess ergänzt im aktuellen Abschnitt die Fächer, die nur in einem Halbjahr unterrichtet werden. Solche Fächer heißen <strong>Epochalfächer</strong>.</p><p><a href="/bilder/vorbereitung/gruppenprozesse-epochal-faecher-2-gruppenprozess.png"><img src="'+o+'" alt="Gruppenprozess zur Übernahme von Fächern und Noten aus einem vorhergehenden Lernabschnitt bei Epochalfächern." loading="lazy"></a></p><p><em>Gruppenprozess zur Übernahme von Fächern und Noten aus einem vorhergehenden Lernabschnitt bei Epochalfächern.</em></p><p>Starten Sie ihn über <em>Gruppenprozesse ➜ Fächer ➜ Noten von Epochal-Fächern ergänzen.</em></p><p><a href="/bilder/vorbereitung/gruppenprozesse-epochal-faecher-1-stundentafel.png"><img src="'+h+'" alt="Konfigurieren eines Faches in einem Jahrgang als Epochal-Fach über die Stundentafel." loading="lazy"></a></p><p><em>Konfigurieren eines Faches in einem Jahrgang als Epochal-Fach über die Stundentafel.</em></p><p>Damit der Gruppenprozess richtig arbeitet, müssen diese Fächer im <em>vorangehenden</em> Abschnitt entsprechend gekennzeichnet sein.</p><p>Setzen Sie dafür den Haken <strong>Epochen-Unterricht</strong>. Wenn das Fach bereits in der Stundentafel als Epochenunterricht markiert ist, werden diese Häkchen bei der Zuweisung mitgesetzt.</p>',10),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),r("Beispiel")]),e("p",null,"Wird Musik in der Jahrgangsstufe 7 nur im ersten Halbjahr unterrichtet und damit auch benotet, so soll diese Note natürlich auch auf dem Versetzungszeugnis erscheinen.")],-1),e("p",null,"Dieser Gruppenprozess ergänzt für die ausgewählte Schülermenge im aktuellen Abschnitt - basierend auf dem vorherigen Abschnitt - sowohl das Fach als auch die Note.",-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Noten_von_Epochal-F%C3%A4chern_erg%C3%A4nzen_(Gruppenprozesse_F%C3%A4cher)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),r(" · Quellrevision 5355.")],-1)])])}const b=a(p,[["render",c]]);export{z as __pageData,b as default};
